import{_ as e}from"./chunks/prontera-city.B6XwNokk.js";import{_ as i,o as l,c as t,ag as r}from"./chunks/framework.DGzMGr_a.js";const _=JSON.parse('{"title":"RO3 核心系统介绍","description":"RO3 赛季制、多元宇宙、GVG 攻城战、百人副本等核心玩法系统全解析","frontmatter":{"title":"RO3 核心系统介绍","description":"RO3 赛季制、多元宇宙、GVG 攻城战、百人副本等核心玩法系统全解析","lastUpdated":true},"headers":[],"relativePath":"guide/systems.md","filePath":"guide/systems.md","lastUpdated":1780230058000}'),o={name:"guide/systems.md"};function s(d,a,h,n,p,c){return l(),t("div",null,[...a[0]||(a[0]=[r('<h1 id="ro3-核心系统介绍" tabindex="-1">RO3 核心系统介绍 <a class="header-anchor" href="#ro3-核心系统介绍" aria-label="Permalink to &quot;RO3 核心系统介绍&quot;">​</a></h1><p><img src="'+e+'" alt="RO3 城市全景"></p><p>了解 RO3 区别于其他 MMO 的特色系统。</p><h2 id="赛季制" tabindex="-1">赛季制 <a class="header-anchor" href="#赛季制" aria-label="Permalink to &quot;赛季制&quot;">​</a></h2><p>每个赛季 3-4 个月，推出新的职业流派与玩法内容。</p><ul><li>「赛」：领地争霸战等竞争玩法</li><li>「季」：资料片式的内容扩充</li><li>新玩家随时可加入，差距不大</li><li>赛季结束后可投票复刻经典赛季</li></ul><h2 id="多元宇宙" tabindex="-1">多元宇宙 <a class="header-anchor" href="#多元宇宙" aria-label="Permalink to &quot;多元宇宙&quot;">​</a></h2><p>新角色「布拉吉丝」带领玩家穿越平行宇宙。</p><ul><li>每个世界拥有独特的文明风貌与挑战</li><li>每次穿越带来新的战斗体验和成长路径</li><li>每个平行世界赋予角色新的职业特质</li><li>随时选择新世界重新启程</li></ul><h2 id="gvg-攻城战" tabindex="-1">GVG 攻城战 <a class="header-anchor" href="#gvg-攻城战" aria-label="Permalink to &quot;GVG 攻城战&quot;">​</a></h2><ul><li>支持 100v100 同场景战斗</li><li>终极目标：千人同场景攻城战</li><li>使用攻城车、云梯、炮台、机甲等器械</li><li>需要团队协作，无法一人攻城</li><li>粮草运输、结盟等策略要素</li></ul><h2 id="百人副本" tabindex="-1">百人副本 <a class="header-anchor" href="#百人副本" aria-label="Permalink to &quot;百人副本&quot;">​</a></h2><p>以「鲲」为主题的 Party Game 副本，强调娱乐性。</p><h2 id="十人副本" tabindex="-1">十人副本 <a class="header-anchor" href="#十人副本" aria-label="Permalink to &quot;十人副本&quot;">​</a></h2><p>不追求输出，强调互动性：玩家×玩家、玩家×场景、玩家×Boss。</p><h2 id="自由交易" tabindex="-1">自由交易 <a class="header-anchor" href="#自由交易" aria-label="Permalink to &quot;自由交易&quot;">​</a></h2><p>经典「摆摊」系统回归，新增信用评分机制。</p><h2 id="自动战斗" tabindex="-1">自动战斗 <a class="header-anchor" href="#自动战斗" aria-label="Permalink to &quot;自动战斗&quot;">​</a></h2><p>自动战斗效率约为手动的 70%-80%，解决日常练级负担。</p>',19)])])}const f=i(o,[["render",s]]);export{_ as __pageData,f as default};
